#!/usr/bin/env python3
"""
Global Intentional Homicide Trends Report Generator
Analyzes UNODC data (1990-2023) and produces a self-contained HTML report.
"""

import pandas as pd
import numpy as np
import json
from datetime import datetime

# ── Load & Prepare ──────────────────────────────────────────────────────────

df = pd.read_csv("/app/benchmark/data.csv")

REGION_MAP = {
    'DZA':'Africa','AGO':'Africa','BEN':'Africa','BWA':'Africa','BFA':'Africa','BDI':'Africa',
