    'HND':'Americas','JAM':'Americas','MEX':'Americas','NIC':'Americas','PAN':'Americas',
    'PRY':'Americas','PER':'Americas','KNA':'Americas','LCA':'Americas','VCT':'Americas',
    'SUR':'Americas','TTO':'Americas','USA':'Americas','URY':'Americas','VEN':'Americas',
    'PRI':'Americas','VIR':'Americas','ABW':'Americas','CUW':'Americas','BMU':'Americas',
    'CYM':'Americas','TCA':'Americas','MSR':'Americas','GLP':'Americas','MTQ':'Americas',
    'ASM':'Americas',
    'AFG':'Asia','ARM':'Asia','AZE':'Asia','BHR':'Asia','BGD':'Asia','BTN':'Asia',
    'BRN':'Asia','KHM':'Asia','CHN':'Asia','CYP':'Asia','GEO':'Asia','IND':'Asia',
    'IDN':'Asia','IRN':'Asia','IRQ':'Asia','ISR':'Asia','JPN':'Asia','JOR':'Asia',
    'KAZ':'Asia','KWT':'Asia','KGZ':'Asia','LAO':'Asia','LBN':'Asia','MYS':'Asia',
    'MDV':'Asia','MNG':'Asia','MMR':'Asia','NPL':'Asia','OMN':'Asia','PAK':'Asia',
    'PSE':'Asia','PHL':'Asia','QAT':'Asia','SAU':'Asia','SGP':'Asia','KOR':'Asia',
    'LKA':'Asia','SYR':'Asia','TWN':'Asia','TJK':'Asia','THA':'Asia','TLS':'Asia',
    'TUR':'Asia','TKM':'Asia','ARE':'Asia','UZB':'Asia','VNM':'Asia','YEM':'Asia',
    'HKG':'Asia','MAC':'Asia','PRK':'Asia',
    'ALB':'Europe','AND':'Europe','AUT':'Europe','BLR':'Europe','BEL':'Europe','BIH':'Europe',
    'BGR':'Europe','HRV':'Europe','CZE':'Europe','DNK':'Europe','EST':'Europe','FIN':'Europe',
    'FRA':'Europe','DEU':'Europe','GRC':'Europe','HUN':'Europe','ISL':'Europe','IRL':'Europe',
    'ITA':'Europe','XKX':'Europe','LVA':'Europe','LIE':'Europe','LTU':'Europe','LUX':'Europe',
    'MLT':'Europe','MDA':'Europe','MNE':'Europe','NLD':'Europe','MKD':'Europe','NOR':'Europe',
    'POL':'Europe','PRT':'Europe','ROU':'Europe','RUS':'Europe','SRB':'Europe','SVK':'Europe',
    'SVN':'Europe','ESP':'Europe','SWE':'Europe','CHE':'Europe','UKR':'Europe','GBR':'Europe',
    'SMR':'Europe','VAT':'Europe','MCO':'Europe','FRO':'Europe','IMN':'Europe','JEY':'Europe',
    'GGY':'Europe','GIB':'Europe',
    'AUS':'Oceania','FJI':'Oceania','KIR':'Oceania','MHL':'Oceania','FSM':'Oceania',
    'NRU':'Oceania','NZL':'Oceania','PLW':'Oceania','PNG':'Oceania','WSM':'Oceania',
    'SLB':'Oceania','TON':'Oceania','TUV':'Oceania','VUT':'Oceania','NCL':'Oceania',
    'GUM':'Oceania','PYF':'Oceania',
}

df["region"] = df["iso_code"].map(REGION_MAP)

# Core subsets
both_all = df[(df["sex"] == "both") & (df["age_group"] == "ALL")].copy()
male_all = df[(df["sex"] == "male") & (df["age_group"] == "ALL")].copy()
female_all = df[(df["sex"] == "female") & (df["age_group"] == "ALL")].copy()

# ── KPI Calculations ────────────────────────────────────────────────────────

# 1. Global Median Homicide Rate (most recent year with good coverage)
# Use 2022 as most recent year with 100+ countries
most_recent_good_year = 2022
recent_data = both_all[both_all["year"] == most_recent_good_year]
global_median = recent_data["homicide_rate"].median()
global_mean = recent_data["homicide_rate"].mean()
countries_reporting_recent = len(recent_data)

# 2. Male-to-Female Ratio
# Merge male and female for overlapping country-years
gender_merge = pd.merge(
    male_all[["country", "year", "homicide_rate"]].rename(columns={"homicide_rate": "male_rate"}),
    female_all[["country", "year", "homicide_rate"]].rename(columns={"homicide_rate": "female_rate"}),
    on=["country", "year"],
)
gender_merge["ratio"] = gender_merge["male_rate"] / gender_merge["female_rate"].replace(0, np.nan)
gender_recent = gender_merge[gender_merge["year"] == most_recent_good_year]
male_female_ratio = gender_recent["ratio"].median()

# Over time
gender_ratio_by_year = gender_merge.groupby("year")["ratio"].median()

# 3. Highest national rate most recent year
highest_row = recent_data.loc[recent_data["homicide_rate"].idxmax()]
highest_country = highest_row["country"]
highest_rate = highest_row["homicide_rate"]

# 4. Decade-over-decade change
def decade_avg(decade_start, decade_end):
    subset = both_all[(both_all["year"] >= decade_start) & (both_all["year"] <= decade_end)]
    return subset.groupby("year")["homicide_rate"].median().mean()

avg_1990s = decade_avg(1990, 1999)
avg_2000s = decade_avg(2000, 2009)
avg_2010s = decade_avg(2010, 2019)
avg_2020s = decade_avg(2020, 2023)

change_90s_00s = ((avg_2000s - avg_1990s) / avg_1990s) * 100
change_00s_10s = ((avg_2010s - avg_2000s) / avg_2000s) * 100
change_10s_20s = ((avg_2020s - avg_2010s) / avg_2010s) * 100

# 5. Reporting Coverage
total_countries = df["country"].nunique()
coverage_by_year = both_all.groupby("year")["country"].nunique()
coverage_rate_recent = (countries_reporting_recent / total_countries) * 100

# ── Section Data ────────────────────────────────────────────────────────────

# Global Overview: median and mean rate by year
yearly_stats = both_all.groupby("year")["homicide_rate"].agg(["median", "mean", "count"]).reset_index()
yearly_stats.columns = ["year", "median_rate", "mean_rate", "num_countries"]

# Regional comparison
both_all_regional = both_all[both_all["region"].notna()].copy()
regional_recent = both_all_regional[both_all_regional["year"] == most_recent_good_year]
regional_stats = regional_recent.groupby("region")["homicide_rate"].agg(["median", "mean", "count"]).reset_index()
regional_stats.columns = ["region", "median_rate", "mean_rate", "num_countries"]
regional_stats = regional_stats.sort_values("median_rate", ascending=False)

# Regional trends over time
regional_yearly = both_all_regional.groupby(["year", "region"])["homicide_rate"].median().reset_index()

# Top 10 / Bottom 10 (use most recent per country, filter out tiny territories for meaningful results)
most_recent_per_country = both_all.sort_values("year", ascending=False).drop_duplicates("country")
# For top 10, include everything; for bottom 10, use only countries with pop > small territories
top10 = most_recent_per_country.nlargest(10, "homicide_rate")[["country", "year", "homicide_rate", "region"]]
# Filter bottom 10 to non-zero for more meaningful analysis
nonzero = most_recent_per_country[most_recent_per_country["homicide_rate"] > 0]
bot10 = nonzero.nsmallest(10, "homicide_rate")[["country", "year", "homicide_rate", "region"]]

# Gender disparity
gender_yearly_global = gender_merge.groupby("year").agg(
    male_median=("male_rate", "median"),
    female_median=("female_rate", "median"),
    ratio_median=("ratio", "median"),
    num_countries=("country", "count"),
).reset_index()

# Gender by region
gender_merge_r = gender_merge.copy()
gender_merge_r["region"] = gender_merge_r["country"].map(
    dict(zip(both_all["country"], both_all["region"]))
)
gender_regional = gender_merge_r[
    (gender_merge_r["year"] == most_recent_good_year) & gender_merge_r["region"].notna()
].groupby("region").agg(
    male_median=("male_rate", "median"),
    female_median=("female_rate", "median"),
    ratio_median=("ratio", "median"),
).reset_index()

# Age group analysis
age_data = df[(df["age_group"] != "ALL") & (df["sex"] == "both")].copy()
age_global = age_data.groupby("age_group")["homicide_rate"].agg(["median", "mean", "count"]).reset_index()
age_global.columns = ["age_group", "median_rate", "mean_rate", "num_obs"]
age_order = ["0_9", "10_14", "15_17", "18_19", "20_24", "25_29", "30_44", "45_59", "60_PLUS"]
age_global["sort_key"] = age_global["age_group"].map({a: i for i, a in enumerate(age_order)})
age_global = age_global.sort_values("sort_key")

