    if len(early) > 0 and len(late) > 0:
        early_avg = early["homicide_rate"].mean()
        late_avg = late["homicide_rate"].mean()
        if early_avg > 0.5:
            pct_change = ((late_avg - early_avg) / early_avg) * 100
            changes.append({
