def get_rate(country, year):
    row = both_all[(both_all["country"] == country) & (both_all["year"] == year)]
    return row["homicide_rate"].values[0] if len(row) > 0 else None

changes = []
for _, row in country_range.iterrows():
    c = row["country"]
    early = both_all[(both_all["country"] == c) & (both_all["year"] <= row["min_year"] + 3)]
    late = both_all[(both_all["country"] == c) & (both_all["year"] >= row["max_year"] - 3)]
    if len(early) > 0 and len(late) > 0:
        early_avg = early["homicide_rate"].mean()
        late_avg = late["homicide_rate"].mean()
        if early_avg > 0.5:
            pct_change = ((late_avg - early_avg) / early_avg) * 100
            changes.append({
                "country": c,
                "early_period": f"{early['year'].min()}-{early['year'].max()}",
                "late_period": f"{late['year'].min()}-{late['year'].max()}",
                "early_avg": early_avg,
                "late_avg": late_avg,
                "pct_change": pct_change,
                "abs_change": late_avg - early_avg,
            })

