def build_rank_table(dataframe, rank_start=1):
    rows_html = ""
    for i, (_, r) in enumerate(dataframe.iterrows(), rank_start):
        rows_html += f"""<tr>
            <td>{i}</td>
            <td>{r['country']}</td>
            <td>{int(r['year'])}</td>
            <td><strong>{r['homicide_rate']:.1f}</strong></td>
            <td>{r.get('region', 'N/A')}</td>
